@register.simple_tag
def icon(name, size=60):
    data = ICONS.get(name) or ICONS['HiconOutlineShieldTick']
    svg = (
        f'<svg width="{size}" height="{size}" viewBox="{data["viewBox"]}" fill="none" '
        f'aria-hidden="true">{data["body"]}</svg>'
    )
    return mark_safe(svg)
